ERL_NIF_TERM
libdecaf_nif_tuak_f4_4(ErlNifEnv *env, int argc, const ERL_NIF_TERM argv[])
{
    if (argc != 4)
        return enif_make_badarg(env);
    ErlNifBinary key;
    if (!enif_inspect_binary(env, argv[0], &key) || (key.size != 16 && key.size != 32))
        return EXCP_BADARG(env, "Key must be a binary of 16 or 32 bytes");
    ErlNifBinary topc;
    if (!enif_inspect_binary(env, argv[1], &topc) || (topc.size != 32))
        return EXCP_BADARG(env, "TOPc must be a binary of 32 bytes");
    ErlNifBinary rand;
    if (!enif_inspect_binary(env, argv[2], &rand) || (rand.size != 16))
        return EXCP_BADARG(env, "RAND must be a binary of 16 bytes");
    libdecaf_nif_tuak_options_t options = {
        .mac_length = 8,
        .res_length = 8,
        .ck_length = 16,
        .ik_length = 16,
        .iterations = 1,
    };
    const libdecaf_nif_tuak_option_t accepted[] = {
        {ATOM(res_length), &options.res_length, libdecaf_nif_tuak_res_lengths, 4},
        {ATOM(ck_length), &options.ck_length, libdecaf_nif_tuak_ck_lengths, 2},
        {ATOM(ik_length), &options.ik_length, libdecaf_nif_tuak_ik_lengths, 2},
        {ATOM(iterations), &options.iterations, NULL, 0},
    };
    if (!libdecaf_nif_tuak_options(env, argv[3], accepted, sizeof(accepted) / sizeof(accepted[0])))
        return EXCP_BADARG(env, "TUAK f4 options must contain valid values for res_length, ck_length, ik_length, iterations only");
    libdecaf_nif_tuak_trap_t *trap = enif_alloc_resource(libdecaf_nif_tuak_resource_type, sizeof(*trap));
    if (trap == NULL)
        return EXCP_ERROR(env, "Cannot allocate TUAK evaluation");
    decaf_bzero(trap, sizeof(*trap));
    trap->options = options;
    trap->remaining = options.iterations;
    trap->operation = ATOM(tuak_f4);
    uint8_t instance =
        (uint8_t)(0x40 | (options.res_length & 0x38) | ((options.ck_length >> 3) & 0x04) | ((options.ik_length >> 4) & 0x02));
    libdecaf_nif_tuak_prepare(trap->state, key.data, key.size, topc.data, instance, rand.data, NULL, NULL);
    ERL_NIF_TERM argument = enif_make_resource(env, trap);
    enif_release_resource(trap);
    return libdecaf_nif_tuak_continue(env, 1, &argument);
}

